package com.combatgearorganizer.slayer;

import java.util.Collections;
import java.util.List;
import java.util.Map;
import lombok.Data;

/**
 * Bundled slayer location data, read from slayer_locations.json with Gson.
 * Generated by tools/build_slayer_locations.py; see NOTICE.md for where the data comes from.
 */
@Data
public class SlayerLocationData
{
	private List<TaskEntry> tasks = Collections.emptyList();

	@Data
	public static class TaskEntry
	{
		/** The game's task id, as stored in the SLAYER_TARGET varp. */
		private int taskId;
		private String name;
		/** Key of the location to suggest first. */
		private String recommended;
		private List<LocationEntry> locations = Collections.emptyList();
		/** Krystilia's Wilderness-only list for this task. */
		private List<LocationEntry> wildernessLocations = Collections.emptyList();
		/** What to bring and expect. Null when the data has none. */
		private TaskInfo info;
		/** Each monster that counts for the task, lowest level first; superiors and bosses last. */
		private List<Variant> variants = Collections.emptyList();
	}

	/** One monster that counts for a task, from the OSRS Wiki. Several game versions are folded into ranges. */
	@Data
	public static class Variant
	{
		private String name;
		/** [lowest, highest] combat level. */
		private int[] level;
		/** [lowest, highest] hitpoints; may be null. */
		private int[] hitpoints;
		/** [lowest, highest] slayer XP per kill. */
		private double[] xp;
		/** "melee", "ranged" and/or "magic": how the monster attacks you. */
		private List<String> attackTypes = Collections.emptyList();
		/** Null when the wiki lists no elemental weakness. */
		private VariantWeakness weakness;
		/** Superiors only appear while on task, by chance. */
		private boolean superior;
		private boolean boss;
		/** Keys of the task's places where this monster spawns. */
		private List<String> places = Collections.emptyList();
		/** For a superior: the name of the monster it replaces. */
		private String superiorOf;
		/** Its own rare drops, rarest first. */
		private List<Drop> drops = Collections.emptyList();
		/** What it always drops worth naming: bones or ashes. */
		private List<String> alwaysDrops = Collections.emptyList();
		/** Prayer and storage items worth bringing for it (bonecrusher, herb sack...). */
		private List<Carry> carry = Collections.emptyList();

		public boolean isRegular()
		{
			return !superior && !boss;
		}
	}

	@Data
	public static class Carry
	{
		/** A {@link CarryItem} key, e.g. "herbSack". */
		private String item;
		/** For drop-based items: about one drop in this many kills. Null for rule-based ones (bonecrusher). */
		private Integer per;
	}

	@Data
	public static class Drop
	{
		private String item;
		/** "1/10,000" */
		private String rarity;
		/** The better rate while on task, when there is one. */
		private String onTask;
		/** [lowest, highest] stack size when it can be more than one; null for one. */
		private int[] quantity;
		/** True when it's a collection log slot. */
		private boolean clog;
	}

	@Data
	public static class VariantWeakness
	{
		/** "air", "water", "earth" or "fire". */
		private String element;
		private Integer percent;
	}

	/** Short notes from the wiki, as written in the source data. Any field can be null. */
	@Data
	public static class TaskInfo
	{
		/** Prose, e.g. "Air spells: 30 to 50% elemental weakness." */
		private String weakness;
		/** Short form when the weakness is elemental, e.g. "Air 30 to 50%". */
		private String elementalWeakness;
		/** Style to kill them with, e.g. "Melee or magic (barrage)". */
		private String style;
		private String monsterAttackStyle;
		private String protectionPrayer;
		private String requiredItems;
		private String notableDrops;
	}

	@Data
	public static class LocationEntry
	{
		private String key;
		private String label;
		/** Spawn tiles (or the entrance) outside the Wilderness, as [x, y, plane]. */
		private List<int[]> points = Collections.emptyList();
		/** Spawn tiles inside the Wilderness. */
		private List<int[]> wildernessPoints = Collections.emptyList();
		/** The game's slayer area id, used to match Konar's assigned area. */
		private Integer areaId;
		/** "multi", "single" or "mixed". */
		private String combat;
		/** "yes" or "no". */
		private String cannon;
		private String note;
		/** Quests and skills needed to get in. Null when there are none. */
		private Requirements requirements;
	}

	@Data
	public static class Requirements
	{
		/** RuneLite {@code Quest} enum names that must be finished. */
		private List<String> questsFinished = Collections.emptyList();
		/** RuneLite {@code Quest} enum names that must at least be started. */
		private List<String> questsStarted = Collections.emptyList();
		/** RuneLite {@code Skill} enum name to the real level needed. */
		private Map<String, Integer> skills = Collections.emptyMap();
	}

	public TaskEntry findTask(int taskId, String name)
	{
		for (TaskEntry task : tasks)
		{
			if (task.taskId == taskId)
			{
				return task;
			}
		}
		if (name != null)
		{
			for (TaskEntry task : tasks)
			{
				if (task.name.equalsIgnoreCase(name.trim()))
				{
					return task;
				}
			}
		}
		return null;
	}
}
